  "The layout field '{field}' belongs to the row, not to its params.": "Le champ de disposition « {field} » relève de la ligne, et non de ses paramètres (params).",
  "The loaded font is {loaded}, not {names}.": "La police chargée est {loaded}, et non {names}.",
